<?php
namespace App\Services\AI;
use App\Models\{NotebookDocument,NotebookDocumentChunk,User}; use Illuminate\Http\UploadedFile; use Illuminate\Support\Facades\{DB,Http,Storage}; use Illuminate\Support\Str; use RuntimeException;
class NotebookService {
 public function list(User $u){return NotebookDocument::where('user_id',$u->id)->latest()->get()->map(fn($d)=>$this->data($d));}
 public function data(NotebookDocument $d):array{return ['id'=>$d->id,'original_filename'=>$d->original_filename,'size_bytes'=>$d->size_bytes,'status'=>$d->status,'error_message'=>$d->status==='failed'?$d->error_message:null,'title'=>$d->title,'summary'=>$d->summary,'chunk_count'=>$d->chunk_count,'created_at'=>$d->created_at?->toISOString(),'updated_at'=>$d->updated_at?->toISOString()];}
 public function ingest(User $u,UploadedFile $f):NotebookDocument { $id=(string)Str::uuid(); $d=NotebookDocument::create(['id'=>$id,'user_id'=>$u->id,'original_filename'=>$f->getClientOriginalName()?:'document.pdf','storage_path'=>"notebook/{$u->id}/{$id}/source.pdf",'size_bytes'=>$f->getSize(),'status'=>'processing','chunk_count'=>0]); try { $stream=fopen($f->getRealPath(),'rb'); Storage::disk('notebook')->put($d->storage_path,$stream); fclose($stream); $r=Http::withHeader('X-Service-Token',(string)config('services.ai.token'))->timeout(90)->attach('file',fopen($f->getRealPath(),'rb'),$d->original_filename,['Content-Type'=>'application/pdf'])->post(rtrim(AiServiceUrl::configured(),'/').'/v1/notebook/ingest'); if($r->failed()) throw new RuntimeException('Không thể xử lý PDF.'); $p=$r->json(); if(($p['dimensions']??0)!==384||!is_array($p['chunks']??null)) throw new RuntimeException('Phản hồi xử lý tài liệu không hợp lệ.'); DB::transaction(function()use($d,$p){foreach($p['chunks'] as $c) NotebookDocumentChunk::create(['id'=>(string)Str::uuid(),'document_id'=>$d->id,'position'=>$c['position'],'page'=>$c['page'],'content'=>$c['content'],'content_hash'=>hash('sha256',$c['content']),'embedding'=>'['.implode(',',$c['embedding']).']']);$d->update(['status'=>'ready','title'=>$p['title'],'summary'=>$p['summary'],'chunk_count'=>count($p['chunks']),'error_message'=>null]);}); } catch(\Throwable $e){$d->update(['status'=>'failed','error_message'=>'Không thể xử lý tài liệu.']);} return $d->fresh(); }
 public function delete(User $u,NotebookDocument $d):void { abort_unless($d->user_id===$u->id,404); try{Storage::disk('notebook')->delete($d->storage_path);}catch(\Throwable $e){throw new RuntimeException('Không thể xóa tệp.');}$d->delete(); }
 public function query(User $u,string $q,array $ids):array { $docs=NotebookDocument::where('user_id',$u->id)->where('status','ready')->when($ids,fn($x)=>$x->whereIn('id',$ids))->get(); if($docs->isEmpty()) return ['answer'=>'Không tìm thấy thông tin trong tài liệu đã chọn.','citations'=>[]]; $vector=Http::withHeader('X-Service-Token',(string)config('services.ai.token'))->post(rtrim(AiServiceUrl::configured(),'/').'/v1/cv-rag/embed-query',['query'=>$q])->json('embedding'); $v='['.implode(',',$vector).']';$chunks=NotebookDocumentChunk::whereIn('document_id',$docs->pluck('id'))->select('*')->selectRaw('1 - (embedding OPERATOR(extensions.<=>) ?::extensions.vector) AS similarity',[$v])->orderByRaw('embedding OPERATOR(extensions.<=>) ?::extensions.vector',[$v])->limit(5)->get(); if($chunks->isEmpty()) return ['answer'=>'Không tìm thấy thông tin trong tài liệu đã chọn.','citations'=>[]];$names=$docs->keyBy('id');$payload=$chunks->map(fn($c)=>['content'=>$c->content,'page'=>$c->page,'filename'=>$names[$c->document_id]->original_filename])->all();$answer=Http::withHeader('X-Service-Token',(string)config('services.ai.token'))->post(rtrim(AiServiceUrl::configured(),'/').'/v1/notebook/answer',['question'=>$q,'chunks'=>$payload])->json('answer');return ['answer'=>$answer,'citations'=>array_map(fn($c)=>['document_id'=>$c->document_id,'filename'=>$names[$c->document_id]->original_filename,'page'=>$c->page],$chunks->all())]; }
}
